// Срок домена из ответа RDAP (события registration / expiration / last changed)
const row = $('Разбор по типу').item.json;
const events = Array.isArray($json.events) ? $json.events : [];
const ev = events.find(e => e.eventAction === 'expiration');
return {
  json: {
    ...row,
    expires: ev ? ev.eventDate : '',
    check_error: ev ? '' : 'RDAP не вернул срок (зона может не поддерживаться, например .ru и .рф). Внесите дату вручную: kind=manual и due_date.'
  }
};

// Срок сертификата: TLS-рукопожатие. Нужна переменная окружения NODE_FUNCTION_ALLOW_BUILTIN=tls
const tls = require('tls');
const row = $json;
const host = String(row.name).trim();
const port = Number(row.port) || 443;
const expires = await new Promise((resolve) => {
  const socket = tls.connect(
    { host, port, servername: host, rejectUnauthorized: false, timeout: 10000 },
    () => {
      const cert = socket.getPeerCertificate();
      socket.end();
      resolve(cert && cert.valid_to ? new Date(cert.valid_to).toISOString() : '');
    }
  );
  socket.on('error', () => resolve(''));
  socket.on('timeout', () => { socket.destroy(); resolve(''); });
});
return {
  json: {
    ...row,
    expires,
    check_error: expires ? '' : 'Не удалось прочитать сертификат (хост недоступен с сервера n8n или не включён модуль tls).'
  }
};

// Платежи без публичного реестра (хостинг, лицензии, подписки): дата берётся из таблицы
const due = String($json.due_date || '').trim();
const ok = /^\d{4}-\d{2}-\d{2}$/.test(due);
return {
  json: {
    ...$json,
    expires: ok ? new Date(due + 'T00:00:00Z').toISOString() : '',
    check_error: ok ? '' : 'В колонке due_date нужна дата в формате ГГГГ-ММ-ДД.'
  }
};

// НАСТРОЙКИ. Идентификаторы чатов вписывает пользователь (по умолчанию пусто).
const CHAT_MAIN = '';        // chat_id основного чата
const CHAT_ESCALATION = '';  // chat_id второго ответственного (можно оставить пустым)

const KIND = { domain: 'домен', ssl: 'SSL-сертификат', manual: 'платёж' };
const now = new Date();
const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  const label = `${r.name} (${KIND[r.kind] || r.kind}, ${r.provider || 'провайдер не указан'})`;

  if (!r.expires) {
    out.push({ json: { ...r, days: null, level: 'error', chat_id: CHAT_MAIN,
      message: `⚠️ Не удалось проверить: ${label}\n${r.check_error || 'нет данных'}` } });
    continue;
  }

  const d = new Date(r.expires);
  const end = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
  const days = Math.round((end - today) / 86400000);
  const dateStr = d.toISOString().slice(0, 10);
  const sum = Number(r.amount_rub) > 0 ? `\nСумма: ${r.amount_rub} ₽` : '';
  const who = r.owner ? `\nОтветственный: ${r.owner}` : '';
  const tail = `${sum}${who}\nДата окончания: ${dateStr}`;

  let level = 'none';
  let head = '';
  if (days === 14) { level = 'info'; head = '🟡 Через 14 дней'; }
  else if (days === 3) { level = 'warn'; head = '🟠 Через 3 дня'; }
  else if (days === 1) { level = 'escalation'; head = '🔴 Осталось 24 часа'; }
  else if (days === 0) { level = 'escalation'; head = '🔴 Сегодня последний день'; }
  else if (days < 0) { level = 'escalation'; head = `🔴 Просрочено на ${-days} дн.`; }

  const base = { ...r, days, level, message: `${head}: ${label}${tail}` };
  out.push({ json: { ...base, chat_id: CHAT_MAIN } });
  if (level === 'escalation' && CHAT_ESCALATION) {
    out.push({ json: { ...base, chat_id: CHAT_ESCALATION, message: `ЭСКАЛАЦИЯ. ${base.message}` } });
  }
}
return out;
